INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_cjp-cteni-s-porozumenim_0','Text: „Včely žijí v rodinách, které nazýváme včelstva. V létě má včelstvo až šedesát tisíc členů. Většinu z nich tvoří dělnice, které sbírají nektar a pyl, starají se o larvy a hlídají úl. Samečci, trubci, se na práci nepodílejí. Vajíčka klade jediná včelí královna.“ Otázka: Jak se nazývá rodina včel?',ARRAY['trubci','včelstvo','roj','úl']::TEXT[],1,'Odpověď plyne přímo z textu: včelstvo.',1,ARRAY[]::TEXT[],NULL,0,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_1','Text: „Včely žijí v rodinách, které nazýváme včelstva. V létě má včelstvo až šedesát tisíc členů. Většinu z nich tvoří dělnice, které sbírají nektar a pyl, starají se o larvy a hlídají úl. Samečci, trubci, se na práci nepodílejí. Vajíčka klade jediná včelí královna.“ Otázka: Kolik členů má včelstvo v létě?',ARRAY['asi sto','až šest tisíc','až šedesát tisíc','přesně jeden']::TEXT[],2,'Odpověď plyne přímo z textu: až šedesát tisíc.',1,ARRAY[]::TEXT[],NULL,1,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_2','Text: „Včely žijí v rodinách, které nazýváme včelstva. V létě má včelstvo až šedesát tisíc členů. Většinu z nich tvoří dělnice, které sbírají nektar a pyl, starají se o larvy a hlídají úl. Samečci, trubci, se na práci nepodílejí. Vajíčka klade jediná včelí královna.“ Otázka: Kdo sbírá nektar a pyl?',ARRAY['larvy','královna','dělnice','trubci']::TEXT[],2,'Odpověď plyne přímo z textu: dělnice.',1,ARRAY[]::TEXT[],NULL,2,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_3','Text: „Včely žijí v rodinách, které nazýváme včelstva. V létě má včelstvo až šedesát tisíc členů. Většinu z nich tvoří dělnice, které sbírají nektar a pyl, starají se o larvy a hlídají úl. Samečci, trubci, se na práci nepodílejí. Vajíčka klade jediná včelí královna.“ Otázka: Co platí o trubcích?',ARRAY['hlídají úl','sbírají pyl','kladou vajíčka','na práci se nepodílejí']::TEXT[],3,'Odpověď plyne přímo z textu: na práci se nepodílejí.',2,ARRAY[]::TEXT[],NULL,3,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_4','Text: „Včely žijí v rodinách, které nazýváme včelstva. V létě má včelstvo až šedesát tisíc členů. Většinu z nich tvoří dělnice, které sbírají nektar a pyl, starají se o larvy a hlídají úl. Samečci, trubci, se na práci nepodílejí. Vajíčka klade jediná včelí královna.“ Otázka: Kdo ve včelstvu klade vajíčka?',ARRAY['trubci','larvy','všechny dělnice','jediná královna']::TEXT[],3,'Odpověď plyne přímo z textu: jediná královna.',2,ARRAY[]::TEXT[],NULL,4,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_5','Text: „Karlův most je nejstarší dochovaný most přes Vltavu v Praze. Jeho stavbu zahájil roku 1357 Karel IV. Je dlouhý přibližně 516 metrů a stojí na šestnácti pilířích. Dnes po něm nejezdí auta, protože je určen pouze pro chodce.“ Otázka: Kdo zahájil stavbu Karlova mostu?',ARRAY['Karel Čapek','Rudolf II.','Karel IV.','Přemysl Otakar II.']::TEXT[],2,'Odpověď plyne přímo z textu: Karel IV..',2,ARRAY[]::TEXT[],NULL,5,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_6','Text: „Karlův most je nejstarší dochovaný most přes Vltavu v Praze. Jeho stavbu zahájil roku 1357 Karel IV. Je dlouhý přibližně 516 metrů a stojí na šestnácti pilířích. Dnes po něm nejezdí auta, protože je určen pouze pro chodce.“ Otázka: V kterém roce byla zahájena stavba mostu?',ARRAY['1357','1457','1257','1757']::TEXT[],0,'Odpověď plyne přímo z textu: 1357.',3,ARRAY[]::TEXT[],NULL,6,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_7','Text: „Karlův most je nejstarší dochovaný most přes Vltavu v Praze. Jeho stavbu zahájil roku 1357 Karel IV. Je dlouhý přibližně 516 metrů a stojí na šestnácti pilířích. Dnes po něm nejezdí auta, protože je určen pouze pro chodce.“ Otázka: Na kolika pilířích stojí Karlův most?',ARRAY['na šestnácti','na dvanácti','na šesti','na šedesáti']::TEXT[],0,'Odpověď plyne přímo z textu: na šestnácti.',3,ARRAY[]::TEXT[],NULL,7,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_8','Text: „Karlův most je nejstarší dochovaný most přes Vltavu v Praze. Jeho stavbu zahájil roku 1357 Karel IV. Je dlouhý přibližně 516 metrů a stojí na šestnácti pilířích. Dnes po něm nejezdí auta, protože je určen pouze pro chodce.“ Otázka: Proč po mostě nejezdí auta?',ARRAY['je příliš nový','je určen pouze pro chodce','je zavřený','je právě opravován']::TEXT[],1,'Odpověď plyne přímo z textu: je určen pouze pro chodce.',3,ARRAY[]::TEXT[],NULL,8,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_9','Text: „Karlův most je nejstarší dochovaný most přes Vltavu v Praze. Jeho stavbu zahájil roku 1357 Karel IV. Je dlouhý přibližně 516 metrů a stojí na šestnácti pilířích. Dnes po něm nejezdí auta, protože je určen pouze pro chodce.“ Otázka: Jak dlouhý je Karlův most podle textu?',ARRAY['přibližně 516 metrů','přibližně 51 metrů','přibližně 5 kilometrů','přibližně 160 metrů']::TEXT[],0,'Odpověď plyne přímo z textu: přibližně 516 metrů.',4,ARRAY[]::TEXT[],NULL,9,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_10','Text: „Tomáš vstal brzy ráno, protože chtěl stihnout první autobus. Venku mrzlo a z okna byla vidět jen bílá mlha. Rychle snědl chleba s máslem, vzal batoh a vyběhl ze dveří. Na zastávce už stála stará paní s košíkem a usmála se na něj.“ Otázka: Proč Tomáš vstal brzy?',ARRAY['chtěl stihnout první autobus','bál se mlhy','měl hlad','byla mu zima']::TEXT[],0,'Odpověď plyne přímo z textu: chtěl stihnout první autobus.',4,ARRAY[]::TEXT[],NULL,10,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_11','Text: „Tomáš vstal brzy ráno, protože chtěl stihnout první autobus. Venku mrzlo a z okna byla vidět jen bílá mlha. Rychle snědl chleba s máslem, vzal batoh a vyběhl ze dveří. Na zastávce už stála stará paní s košíkem a usmála se na něj.“ Otázka: Jaké bylo ráno podle textu?',ARRAY['svítilo slunce','mrzlo a byla mlha','pršelo','foukal vítr']::TEXT[],1,'Odpověď plyne přímo z textu: mrzlo a byla mlha.',4,ARRAY[]::TEXT[],NULL,11,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_12','Text: „Tomáš vstal brzy ráno, protože chtěl stihnout první autobus. Venku mrzlo a z okna byla vidět jen bílá mlha. Rychle snědl chleba s máslem, vzal batoh a vyběhl ze dveří. Na zastávce už stála stará paní s košíkem a usmála se na něj.“ Otázka: Co Tomáš snědl?',ARRAY['nic','chleba s máslem','kaši','rohlík s džemem']::TEXT[],1,'Odpověď plyne přímo z textu: chleba s máslem.',5,ARRAY[]::TEXT[],NULL,12,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_13','Text: „Tomáš vstal brzy ráno, protože chtěl stihnout první autobus. Venku mrzlo a z okna byla vidět jen bílá mlha. Rychle snědl chleba s máslem, vzal batoh a vyběhl ze dveří. Na zastávce už stála stará paní s košíkem a usmála se na něj.“ Otázka: Kdo stál na zastávce?',ARRAY['řidič autobusu','Tomášův bratr','stará paní s košíkem','malá holčička']::TEXT[],2,'Odpověď plyne přímo z textu: stará paní s košíkem.',5,ARRAY[]::TEXT[],NULL,13,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_14','Text: „Tomáš vstal brzy ráno, protože chtěl stihnout první autobus. Venku mrzlo a z okna byla vidět jen bílá mlha. Rychle snědl chleba s máslem, vzal batoh a vyběhl ze dveří. Na zastávce už stála stará paní s košíkem a usmála se na něj.“ Otázka: Kdo je hlavní postavou textu?',ARRAY['řidič','Tomáš','maminka','stará paní']::TEXT[],1,'Odpověď plyne přímo z textu: Tomáš.',5,ARRAY[]::TEXT[],NULL,14,'c_cjp-cteni-s-porozumenim',NULL,NOW())
